class ConverterToPython:
    """
    A utility class to convert strings to Python objects.
    """

    @staticmethod
    def to_int(value):
        """
        Convert a string to an integer.
        """
        try:
            return int(value)
        except ValueError:
            raise ValueError(f"Cannot convert {value} to an integer.")

    @staticmethod
    def to_float(value):
        """
        Convert a string to a float.
        """
        try:
            return float(value)
        except ValueError:
            raise ValueError(f"Cannot convert {value} to a float.")

    @staticmethod
    def to_bool(value):
        """
        Convert a string to a boolean.
        """
        value = value.lower()
        if value in ('true', '1', 't', 'y', 'yes'):
            return True
        elif value in ('false', '0', 'f', 'n', 'no'):
            return False
        else:
            raise ValueError(f"Cannot convert {value} to a boolean.")

    @staticmethod
    def to_list(value, delimiter=','):
        """
        Convert a string to a list of strings, splitting by the specified delimiter.
        """
        return [item.strip() for item in value.split(delimiter)]

