def recursive_diff(d1, d2, log=False):
    """
    Recursively compares two dictionaries and logs differences if log is True.
    """
    if log:
        print(f"Comparing {d1} and {d2}")

    if isinstance(d1, dict) and isinstance(d2, dict):
        diff = {}
        for key in d1.keys().union(d2.keys()):
